namespace ghidra.feature.vt.gui.actions;







using docking;
using docking;
using docking.action;
using generic.theme;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.editors;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.provider.matchtable;
using ghidra.util;

public class ChooseMatchTagAction : DockingAction {

	private static readonly string MENU_GROUP = VTPlugin.TAG_MENU_GROUP;
	private static readonly Icon EDIT_TAG_ICON = new GIcon("icon.version.tracking.action.choose.tag");
	private static readonly string ACTION_NAME = "Choose Match Tag";

	private VTController controller;
	private VTMatchTag lastTag;

	public ChooseMatchTagAction(VTController controller) : base(ACTION_NAME, VTPlugin.OWNER)
    {
		this.controller = controller;
		setDescription("Choose Match Tag");
		setToolBarData(new ToolBarData(EDIT_TAG_ICON, MENU_GROUP));
		MenuData menuData = new MenuData(new string[] { "Choose Tag" }, EDIT_TAG_ICON, MENU_GROUP);
		menuData.setMenuSubGroup("1"); // 1st in the list
		setPopupMenuData(menuData);
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Choose_Tag"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		if (matches.size() == 0) {
			return;
		}
		JComponent component = context.getComponentProvider().getComponent();
		editTag(matches, component);
	}

	private void editTag(List<VTMatch> matches, JComponent component) {

		if (matches == null || matches.size() == 0) {
			return;
		}
		VTSession session = controller.getSession();
		if (session == null) {
			return;
		}
		TagChooserDialog dialog = new TagChooserDialog(session, matches, component, lastTag);
		dialog.setRememberSize(false);
		SwingUtilities.invokeLater(() => {
			controller.getTool().showDialog(dialog, component);
			lastTag = dialog.getSelectedTag();
		});
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is VTMatchContext)) {
			return false;
		}
		VTMatchContext matchContext = (VTMatchContext) context;
		List<VTMatch> matches = matchContext.getSelectedMatches();
		if (matches.size() == 0) {
			return false;
		}
		return true;
	}

//==================================================================================================
// Inner Classes    
//==================================================================================================

	private class TagChooserDialog : DialogComponentProvider {

		private JPanel editorPanel;
		private MatchTagComboBox tagComboBox;
		private VTSession session;
		private List<VTMatch> matches;
		private JComponent component;

		private VTMatchTag selectedTag;

		protected TagChooserDialog(VTSession session, List<VTMatch> matches,
				JComponent component, VTMatchTag selectedTag) : base("Choose Match Tag", true, true, true, false)
    {
			this.session = session;
			this.matches = matches;
			this.component = component;
			this.selectedTag = selectedTag;
			editorPanel = createEditorPanel();
			addWorkPanel(editorPanel);
			addOKButton();
			addCancelButton();
			setDefaultButton(okButton);
		}

		private JPanel createEditorPanel() {
			JPanel panel = new JPanel(new BorderLayout());
			tagComboBox = new MatchTagComboBox(session, matches, component, selectedTag);
			Dimension dim = new Dimension(50, tagComboBox.getPreferredSize().height);
			tagComboBox.setMinimumSize(dim);
			panel.add(tagComboBox, BorderLayout.CENTER);
			return panel;
		}

		/* @Override */
		protected void cancelCallback() {
			base.cancelCallback();
		}

		/* @Override */
		protected void okCallback() {
			selectedTag = (VTMatchTag) tagComboBox.getSelectedItem();

			tagComboBox.apply();
			close();
		}

		VTMatchTag getSelectedTag() {
			return selectedTag;
		}
	}
}
